// Ported from the Node app's Sequelize model StudyMaterial (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class StudyMaterialConfiguration : IEntityTypeConfiguration<StudyMaterial>
{
    public void Configure(EntityTypeBuilder<StudyMaterial> builder)
    {
        builder.ToTable("study_materials");
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.ClassId).HasColumnName("class_id");
        builder.Property(e => e.SubjectId).HasColumnName("subject_id");
        builder.Property(e => e.Title).HasColumnName("title").HasColumnType("nvarchar(160)").HasMaxLength(160).IsRequired();
        builder.Property(e => e.Url).HasColumnName("url").HasColumnType("nvarchar(500)").HasMaxLength(500).IsRequired();
        builder.Property(e => e.Description).HasColumnName("description").HasColumnType("nvarchar(500)").HasMaxLength(500);
        builder.Property(e => e.CreatedByName).HasColumnName("created_by_name").HasColumnType("nvarchar(100)").HasMaxLength(100);
        builder.Property(e => e.CreatedAt).HasColumnName("created_at").HasColumnType("datetime2");
        builder.HasOne(e => e.SchoolClass).WithMany(p => p.StudyMaterials).HasForeignKey(e => e.ClassId).OnDelete(DeleteBehavior.NoAction);
        builder.HasOne(e => e.Subject).WithMany(p => p.StudyMaterials).HasForeignKey(e => e.SubjectId).OnDelete(DeleteBehavior.NoAction);
    }
}
